const settings = $('Load Global Settings').first()?.json ?? {};
const request = $('Send Member List Email Webhook').first()?.json ?? $input.first()?.json ?? {};
const body = request.body ?? {};
const headers = request.headers ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const truthy = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(clean(value).toLowerCase());
const deriveBaseUrl = (sourceHeaders, fallback) => {
  const forwardedProto = clean(sourceHeaders['x-forwarded-proto']);
  const forwardedHost = clean(sourceHeaders['x-forwarded-host']);
  const host = forwardedHost || clean(sourceHeaders.host);
  const forwardedPort = clean(sourceHeaders['x-forwarded-port']);
  if (!host) return fallback;
  const proto = forwardedProto || 'http';
  let authority = host;
  if (forwardedPort && !authority.includes(':')) {
    const isDefaultPort = (proto === 'http' && forwardedPort === '80') || (proto === 'https' && forwardedPort === '443');
    if (!isDefaultPort) authority = authority + ':' + forwardedPort;
  }
  return proto + '://' + authority;
};
const listOptions = {"non_renewed_members": {"label": "Members Who Have Not Renewed This Year", "description": "People who were members last season and do not currently appear in this season's paid membership package set."}, "current_members": {"label": "Current Members", "description": "Current-season paid members with a resolved email address."}, "contacts_without_current_membership": {"label": "Contacts Without Current Membership", "description": "Current contacts with email who do not match a current paid member."}};
const fallbackBaseUrl = 'http://n8n:5678';
const n8nBaseUrl = deriveBaseUrl(headers, fallbackBaseUrl);
const listKey = Object.prototype.hasOwnProperty.call(listOptions, clean(body.list_key)) ? clean(body.list_key) : '';
const option = listOptions[listKey] || null;
const renderedSubject = clean(body.rendered_subject);
const renderedMessage = clean(body.rendered_message);
const renderedSignature = body.rendered_signature ?? '';
const returnUrl = clean(body.return_url) || (n8nBaseUrl + '/webhook/member-list-mailout');
const deliveryMode = truthy(body.test_mode) ? 'test' : 'production';
const errorMessage = !listKey ? 'A valid recipient list is required.' : (!renderedSubject ? 'rendered_subject is required.' : (!renderedMessage ? 'rendered_message is required.' : ''));
return [{ json: {
  list_key: listKey,
  list_label: option?.label || '',
  list_description: option?.description || '',
  template_key: clean(body.template_key),
  signature_template_key: clean(body.signature_template_key),
  sender_name: clean(settings.email_sender_name) || 'Steve Short',
  reply_to: clean(settings.email_reply_to) || 'members.avondaleltc@gmail.com',
  delivery_mode: deliveryMode,
  test_recipient: clean(settings.email_test_recipient) || 'steve.short@gmail.com',
  return_url: returnUrl,
  rendered_subject: renderedSubject,
  rendered_message: renderedMessage,
  rendered_signature: renderedSignature,
  email_type: clean(body.email_type).toLowerCase() === 'html' ? 'html' : 'text',
  n8n_base_url: n8nBaseUrl,
  error_message: errorMessage
} }];

const input = $('Resolve Send Request').first()?.json ?? {};
const context = (() => { try { return $('Load Send Context').first()?.json ?? {}; } catch { return {}; } })();
const message = context.error_message || input.error_message || 'Unable to send the mailout.';
const returnUrl = input.return_url || '#';
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mailout not sent</title><style>body{margin:0;padding:24px;background:#f4f7fb;font-family:Lato,Arial,sans-serif;color:#1f2937}.panel{max-width:760px;margin:0 auto;background:#fff;border:1px solid #d8e1ec;border-radius:20px;box-shadow:0 18px 40px rgba(15,23,42,.08);padding:28px}h1{margin:0 0 10px;font-size:30px}.message{margin:18px 0;padding:14px 16px;border-radius:14px;background:#fef3f2;color:#b42318;font-weight:700}.button{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;border-radius:999px;text-decoration:none;font-weight:700;background:linear-gradient(135deg,#0f766e 0%,#115e59 100%);color:#fff}</style></head><body><div class="panel"><h1>Mailout Not Sent</h1><p>The member-list mailout could not be completed.</p><div class="message">' + escapeHtml(message) + '</div><a class="button" href="' + escapeHtml(returnUrl) + '">Back to Mailout App</a></div></body></html>';
return [{ json: { html } }];

const input = $('Resolve Send Request').first()?.json ?? {};
const context = $('Load Send Context').first()?.json ?? {};
const parseMaybe = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const recipients = Array.isArray(parseMaybe(context.recipients, [])) ? parseMaybe(context.recipients, []) : [];
const normalized = new Set();
const dedupedRecipients = recipients.filter((recipient) => {
  const email = clean(recipient.recipient_email).toLowerCase();
  if (!email || normalized.has(email)) return false;
  normalized.add(email);
  return true;
});
const chunkSize = 50;
const chunk = (values, size) => {
  const groups = [];
  for (let index = 0; index < values.length; index += size) groups.push(values.slice(index, index + size));
  return groups;
};
const recipientEmails = dedupedRecipients.map((recipient) => clean(recipient.recipient_email)).filter(Boolean);
const actualGroups = input.delivery_mode === 'production'
  ? chunk(recipientEmails, chunkSize)
  : [[input.test_recipient].filter(Boolean)];
const combinedMessage = input.email_type === 'html'
  ? [String(input.rendered_message ?? ''), String(input.rendered_signature ?? '')].filter((value) => clean(value)).join('')
  : [clean(input.rendered_message), clean(input.rendered_signature)].filter(Boolean).join('\n\n');
return actualGroups.map((group, index) => ({
  json: {
    list_key: input.list_key,
    list_label: input.list_label,
    template_key: input.template_key,
    delivery_mode: input.delivery_mode,
    sender_name: input.sender_name,
    reply_to: input.reply_to,
    return_url: input.return_url,
    rendered_subject: input.rendered_subject,
    rendered_message: combinedMessage,
    email_type: input.email_type,
    visible_to: input.reply_to,
    intended_recipient_count: recipientEmails.length,
    actual_recipient_count: group.length,
    actual_bcc: group.join(', '),
    recipient_sample: dedupedRecipients.slice(0, 8),
    chunk_index: index + 1,
    chunk_count: actualGroups.length,
    current_season: clean(context.current_season),
    previous_season: clean(context.previous_season),
    test_recipient: input.test_recipient
  }
}));

const payloads = $('Build Chunk Payloads').all().map((item) => item.json ?? {});
const first = payloads[0] ?? {};
const sendResponses = $input.all().map((item) => item.json ?? {});
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const modeLabel = first.delivery_mode === 'production' ? 'Production' : 'Test';
const chunkCount = payloads.length;
const deliveredCount = payloads.reduce((total, item) => total + Number(item.actual_recipient_count || 0), 0);
const chunkSummary = payloads.map((item) => String(item.actual_recipient_count || 0)).join(', ');
const gmailIds = sendResponses.map((item) => item.gmail_message_id).filter(Boolean).join(', ');
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mailout sent</title><style>body{margin:0;padding:24px;background:#f4f7fb;font-family:Lato,Arial,sans-serif;color:#1f2937}.panel{max-width:860px;margin:0 auto;background:#fff;border:1px solid #d8e1ec;border-radius:20px;box-shadow:0 18px 40px rgba(15,23,42,.08);padding:28px}.pill{display:inline-flex;align-items:center;padding:8px 12px;border-radius:999px;background:#edfdf9;color:#115e59;font-weight:700;margin:12px 0 18px}dl{display:grid;grid-template-columns:max-content 1fr;gap:10px 16px;margin:0}dt{font-weight:700}dd{margin:0}.button{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;border-radius:999px;text-decoration:none;font-weight:700;background:linear-gradient(135deg,#0f766e 0%,#115e59 100%);color:#fff}.actions{margin-top:22px}</style></head><body><div class="panel"><h1 style="margin:0 0 10px;font-size:30px;">Mailout Sent</h1><p>The member-list mailout completed through the shared Gmail transport.</p><div class="pill">' + escapeHtml(modeLabel) + ' mode</div><dl><dt>Recipient list</dt><dd>' + escapeHtml(first.list_label || first.list_key || '') + '</dd><dt>Template</dt><dd>' + escapeHtml(first.template_key || '') + '</dd><dt>Resolved recipients</dt><dd>' + escapeHtml(String(first.intended_recipient_count || 0)) + '</dd><dt>Delivered recipients</dt><dd>' + escapeHtml(String(deliveredCount)) + '</dd><dt>BCC chunks</dt><dd>' + escapeHtml(String(chunkCount)) + ' (' + escapeHtml(chunkSummary || '0') + ')</dd><dt>Subject</dt><dd>' + escapeHtml(first.rendered_subject || '') + '</dd>' + (gmailIds ? '<dt>Gmail message ids</dt><dd>' + escapeHtml(gmailIds) + '</dd>' : '') + '</dl><div class="actions"><a class="button" href="' + escapeHtml(first.return_url || '#') + '">Back to Mailout App</a></div></div></body></html>';
return [{ json: { html } }];
